-- Unified budget identities: no fake HR balances or changes to imported leave data.
create function private.budget_schedules_valid(items jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare s jsonb; h jsonb; total numeric; begin
 if jsonb_typeof(items)<>'array' or jsonb_array_length(items)>60 then return false;end if;
 for s in select value from jsonb_array_elements(items) loop
  if s->>'from' is null or to_char((s->>'from')::date,'YYYY-MM-DD')<>s->>'from' or s->>'confirmed' is distinct from 'true' or jsonb_typeof(s->'hours') is distinct from 'array' or jsonb_array_length(s->'hours')<>7 then return false;end if;
  total:=0;for h in select value from jsonb_array_elements(s->'hours') loop
   if h#>>'{}' is null or (h#>>'{}')::numeric not between 0 and 24 or (h#>>'{}')::numeric*60<>trunc((h#>>'{}')::numeric*60) then return false;end if;total:=total+(h#>>'{}')::numeric;
  end loop;if total<=0 or total>84 then return false;end if;
 end loop;
 return (select count(*)=count(distinct value->>'from') from jsonb_array_elements(items));
 exception when others then return false;
end $$;
create table public.hour_budget_registry(
 person_key text primary key,
 imported_person_key text unique references public.leave_people(person_key),
 account_id uuid unique references public.profiles(id),
 schedules jsonb not null default '[]' check(private.budget_schedules_valid(schedules)),
 version int not null default 0,
 check((imported_person_key is not null and person_key=imported_person_key and account_id is null and schedules='[]'::jsonb) or (imported_person_key is null and account_id is not null and person_key='ACCOUNT:'||account_id::text))
);
insert into public.hour_budget_registry(person_key,imported_person_key) select person_key,person_key from public.leave_people;
alter table public.hour_budget_assignments drop constraint hour_budget_assignments_person_key_fkey;
alter table public.hour_budget_days drop constraint hour_budget_days_person_key_fkey;
alter table public.hour_budget_assignments add foreign key(person_key) references public.hour_budget_registry(person_key);
alter table public.hour_budget_days add foreign key(person_key) references public.hour_budget_registry(person_key);
alter table public.hour_budget_registry enable row level security;
revoke all on public.hour_budget_registry from public,anon,authenticated;
grant select,insert,update on public.hour_budget_registry to authenticated;
grant select,insert on public.hour_budget_registry to service_role;
create policy admin_read on public.hour_budget_registry for select to authenticated using(private.is_admin());
create policy admin_insert on public.hour_budget_registry for insert to authenticated with check(private.is_admin());
create policy admin_update on public.hour_budget_registry for update to authenticated using(private.is_admin()) with check(private.is_admin());
create function private.validate_budget_identity() returns trigger language plpgsql security invoker set search_path='' as $$begin
 if tg_op='UPDATE' and (new.person_key,new.imported_person_key,new.account_id) is distinct from (old.person_key,old.imported_person_key,old.account_id) then raise exception 'Identità non modificabile';end if;
 if new.account_id is not null then if not exists(select 1 from public.profiles where id=new.account_id and role='worker' and site='N153') then raise exception 'Scegli un account lavoratore N153';end if;end if;
 if tg_op='UPDATE' then if new.version<>old.version then raise exception 'Versione non valida';end if;new.version:=old.version+1;else new.version:=1;end if;return new;
end $$;
create trigger validate_identity before insert or update on public.hour_budget_registry for each row execute function private.validate_budget_identity();
create trigger audit_identity after insert or update on public.hour_budget_registry for each row execute function private.audit_hour_budget();
create or replace function private.hour_budget_account(k text) returns uuid language sql security definer set search_path='' as $$
 select coalesce(p.account_id,r.account_id) from public.hour_budget_registry r left join public.leave_people p on p.person_key=r.imported_person_key where r.person_key=k and private.is_admin()
$$;
create function private.register_imported_budget_person() returns trigger language plpgsql security invoker set search_path='' as $$begin
 insert into public.hour_budget_registry(person_key,imported_person_key) values(new.person_key,new.person_key) on conflict(person_key) do nothing;return new;end $$;
-- Import service retains its existing interface. Only the budget identity is added.
grant insert on public.hour_budget_audit to service_role;
grant usage on sequence public.hour_budget_audit_id_seq to service_role;
-- service role inserts generated by HR imports have no end-user JWT; do not attach admin audit to those inserts.
drop trigger audit_identity on public.hour_budget_registry;
create function private.audit_budget_identity() returns trigger language plpgsql security invoker set search_path='' as $$begin
 if auth.uid() is not null then insert into public.hour_budget_audit(table_name,old_value,new_value) values(tg_table_name,case when tg_op='UPDATE' then to_jsonb(old) else null end,to_jsonb(new));end if;return new;end $$;
create trigger audit_identity after insert or update on public.hour_budget_registry for each row execute function private.audit_budget_identity();
create trigger budget_person_insert after insert on public.leave_people for each row execute function private.register_imported_budget_person();
